+const temp = () => mkdtempSync(join(tmpdir(), 'journal-check-'));
+const jsonl = (rows) => rows.map((r) => JSON.stringify(r)).join('\n') + '\n';
+const run = (args) => spawnSync(process.execPath, [BIN, ...args], { encoding: 'utf8', env: { PATH: process.env.PATH } });
